    select * FROM (
        select ROWNUM as rnum, A.* from (
        	select cm.*,
        		(select count(*) from dc_comment where cmt_type_no = cm.comm_no) as reply_count
        	from dc_community cm


                    AND cm.comm_type = #{comm_type}


                    AND cm.comm_pet_type = #{comm_pet_type}


                    AND cm.comm_category = #{comm_category}




                    ORDER BY cm.comm_good DESC NULLS LAST, cm.comm_view DESC NULLS LAST, cm.comm_no DESC


                    ORDER BY cm.comm_date DESC


	        ) A
	        WHERE ROWNUM <= #{endRow}
	    )
	    WHERE rnum >= #{startRow}

    SELECT * FROM (
	    SELECT cm.*,
	        (SELECT count(*) FROM dc_comment WHERE cmt_type_no = cm.comm_no) AS reply_count
	    FROM dc_community cm


	            AND comm_type = #{comm_type}


	            AND comm_pet_type = #{comm_pet_type}


	    ORDER BY NVL(comm_good, 0) DESC, NVL(comm_view, 0) DESC, comm_no DESC
    )
    WHERE ROWNUM <= 10

